package com.familya.sharing.adapter.out.events; import com.familya.sharing.application.port.out.ShareChangePublisher; import com.familya.sharing.domain.model.ShareLink; import com.familya.platform.outbox.*; import org.springframework.stereotype.Component; import java.util.*; @Component public class OutboxShareChangePublisher implements ShareChangePublisher {private final OutboxWriter outbox;public OutboxShareChangePublisher(OutboxWriter o){outbox=o;}public void created(ShareLink l){stage(l,"ShareLinkCreated",Map.of("treeId",l.treeId().toString(),"shareId",l.id().toString(),"scope",l.scope().name(),"role",l.role().name()));}public void revoked(ShareLink l){stage(l,"ShareLinkRevoked",Map.of("treeId",l.treeId().toString(),"shareId",l.id().toString(),"revokedAt",l.revokedAt().toString()));}public void projectionRebuilt(UUID t,long w,long v){stage(t,t,"ShareProjectionRebuilt",v,Map.of("treeId",t.toString(),"watermark",w,"version",v));}private void stage(ShareLink l,String e,Map<String,Object> p){stage(l.id(),l.treeId(),e,l.revision(),p);}private void stage(UUID id,UUID tree,String e,long v,Map<String,Object> p){outbox.stage(JdbcOutboxWriter.builder().create("share",id.toString(),v,e,1,"sharing.events.v1",tree.toString(),p).build());}}
